metadata.rules_text:
{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is negative or shows early negative momentum.",
    "Reduce forecast overshoots following sharp price spikes by applying a 10-15% dampening factor.",
    "Apply mean reversion bias: if forecast deviates >5% from recent 7-day average, adjust toward it.",
    "Increase forecast sensitivity to sentiment shifts in the last 5 days — especially if sentiment turns positive after a dip.",
    "Avoid over-optimism in early forecast periods; lag the forecast by 1-2 days if sentiment is neutral or weak."
  ]
}
